def p1():
    total = 0
    input = ""
    for c in input:
        match c:
            case "B":
                total += 1
            case "C":
                total += 3

    print(total)

def p2():
    potions = [0, 1, 3, 5]
    offset = ord('A')
    total = 0
    input = ""

    for i in range(0, input.__len__(), 2):
        count = 0

        if input[i] != 'x':
            total += potions[ord(input[i]) - offset]
            count += 1
        if input[i + 1] != 'x':
            total += potions[ord(input[i + 1]) - offset]
            count += 1

        if (count == 2): total += 2

    print(total)


def p3():
    potions = [0, 1, 3, 5]
    offset = ord('A')
    total = 0
    input = ""

    for i in range(0, input.__len__(), 3):
        count = 0

        for ii in range(3):
            if input[i + ii] != 'x':
                total += potions[ord(input[i + ii]) - offset]
                count += 1


        if (count == 2): total += 2
        elif (count == 3): total += 6

    print(total)



p3()